const _params = function params(htl, Inputs){return( Inputs.form({
  adCost: Inputs.range([0, 100], {value: 30, step: 1, label: "Ad Cost ($k / quarter)"}),
  marketGainFromAd: Inputs.range([0, 100], {value: 40, step: 1, label: "Market gain if you Ad & rival doesn't ($k)"}),
  bothAdGain: Inputs.range([0, 100], {value: 15, step: 1, label: "Market gain each if both Advertise ($k) — split benefit"}),
  baseProfit: Inputs.range([0, 200], {value: 100, step: 1, label: "Baseline profit — no ads for either ($k / quarter)"),
  nameYou: Inputs.text({value: "You", label: "Your firm name"}),
  nameRival: Inputs.text({value: "Competitor", label: "Rival firm name"}),
}) )};

const _gameMatrix = function gameMatrix(params){return(
  (() => {
    const { adCost, marketGainFromAd, bothAdGain, baseProfit } = params;
    // Payoff matrix: [you, rival]
    // Row = your strategy (Ad, NoAd), Col = rival strategy (Ad, NoAd)
    const youAd_rivalAd     = baseProfit + bothAdGain - adCost;
    const youAd_rivalNoAd   = baseProfit + marketGainFromAd - adCost;
    const youNoAd_rivalAd   = baseProfit - marketGainFromAd * 0.3;  // lose some market
    const youNoAd_rivalNoAd = baseProfit;

    const rivalAd_youAd     = baseProfit + bothAdGain - adCost;
    const rivalAd_youNoAd   = baseProfit + marketGainFromAd - adCost;
    const rivalNoAd_youAd   = baseProfit - marketGainFromAd * 0.3;
    const rivalNoAd_youNoAd = baseProfit;

    return {
      you: {
        Ad:    { Ad: youAd_rivalAd,    NoAd: youAd_rivalNoAd },
        NoAd:  { Ad: youNoAd_rivalAd,  NoAd: youNoAd_rivalNoAd },
      },
      rival: {
        Ad:    { Ad: rivalAd_youAd,    NoAd: rivalAd_youNoAd },
        NoAd:  { Ad: rivalNoAd_youAd,  NoAd: rivalNoAd_youNoAd },
      },
      raw: {
        adCost, marketGainFromAd, bothAdGain, baseProfit,
      }
    };
  })()
)};

const _equilibrium = function equilibrium(gameMatrix, params){return(
  (() => {
    const { you, rival } = gameMatrix;
    const result = { pureEquilibria: [], mixedStrategy: null, dominantStrategies: {} };

    // Check pure strategy Nash equilibria
    const strategies = ["Ad", "NoAd"];
    for (const y of strategies) {
      for (const r of strategies) {
        // Check if y is best response to r
        const yPayoffs_r = you.Ad[r] >= you.NoAd[r] ? "Ad" : "NoAd";
        const isYouBest = y === yPayoffs_r || you.Ad[r] === you.NoAd[r];

        // Check if r is best response to y
        const rPayoffs_y = rival.Ad[y] >= rival.NoAd[y] ? "Ad" : "NoAd";
        const isRivalBest = r === rPayoffs_y || rival.Ad[y] === rival.NoAd[y];

        if (isYouBest && isRivalBest) {
          result.pureEquilibria.push({
            you: y, rival: r,
            yourPayoff: you[y][r], rivalPayoff: rival[r][y],
          });
        }
      }
    }

    // Mixed strategy Nash equilibrium
    // You play Ad with probability p such that rival is indifferent
    // Rival plays Ad with probability q such that you are indifferent
    const rivalIndiff_top = rival.NoAd.Ad - rival.NoAd.NoAd;  // rival's NoAd payoff diff
    const rivalIndiff_bot = (rival.Ad.Ad - rival.Ad.NoAd) - (rival.NoAd.Ad - rival.NoAd.NoAd);
    const youIndiff_top = you.Ad.NoAd - you.NoAd.NoAd;
    const youIndiff_bot = (you.Ad.Ad - you.Ad.NoAd) - (you.NoAd.Ad - you.NoAd.NoAd);

    if (Math.abs(rivalIndiff_bot) > 0.001 && Math.abs(youIndiff_bot) > 0.001) {
      const p = rivalIndiff_top / rivalIndiff_bot;  // prob you play Ad
      const q = youIndiff_top / youIndiff_bot;       // prob rival plays Ad
      if (p > 0 && p < 1 && q > 0 && q < 1) {
        const expectedYou = p * (q * you.Ad.Ad + (1-q) * you.Ad.NoAd) +
                           (1-p) * (q * you.NoAd.Ad + (1-q) * you.NoAd.NoAd);
        const expectedRival = q * (p * rival.Ad.Ad + (1-p) * rival.Ad.NoAd) +
                             (1-q) * (p * rival.NoAd.Ad + (1-p) * rival.NoAd.NoAd);
        result.mixedStrategy = {
          pYouAd: p, qRivalAd: q,
          yourExpectedPayoff: expectedYou, rivalExpectedPayoff: expectedRival,
        };
      }
    }

    // Dominant strategies
    for (const player of ["you", "rival"]) {
      const p = gameMatrix[player];
      const AdBetterAlways = p.Ad.Ad >= p.NoAd.Ad && p.Ad.NoAd >= p.NoAd.NoAd;
      const NoAdBetterAlways = p.NoAd.Ad >= p.Ad.Ad && p.NoAd.NoAd >= p.Ad.NoAd;
      if (AdBetterAlways && !NoAdBetterAlways) result.dominantStrategies[player] = "Ad";
      else if (NoAdBetterAlways && !AdBetterAlways) result.dominantStrategies[player] = "NoAd";
      else result.dominantStrategies[player] = null; // no dominant strategy
    }

    return result;
  })()
)};

