const _equilibriumReport = function equilibriumReport(equilibrium, params, gameMatrix, md){
  const e = equilibrium;
  const dom = e.dominantStrategies;
  const lines = ["## 📊 Equilibrium Analysis", ""];

  // Dominant strategies
  if (dom.you) lines.push(`**${params.nameYou}** has a dominant strategy: **${dom.you === "Ad" ? "Advertise ✅" : "Don't Advertise ❌"}**`);
  else lines.push(`**${params.nameYou}** has no dominant strategy (best response depends on rival).`);
  if (dom.rival) lines.push(`**${params.nameRival}** has a dominant strategy: **${dom.rival === "Ad" ? "Advertise ✅" : "Don't Advertise ❌"}**`);
  else lines.push(`**${params.nameRival}** has no dominant strategy (best response depends on rival).`);

  lines.push("");

  // Pure equilibria
  if (e.pureEquilibria.length > 0) {
    lines.push(`### Pure-Strategy Nash Equilibria (${e.pureEquilibria.length})`);
    for (const eq of e.pureEquilibria) {
      lines.push(`- **${params.nameYou}: ${eq.you}**, **${params.nameRival}: ${eq.rival}** → payoffs (${eq.yourPayoff.toFixed(1)}k, ${eq.rivalPayoff.toFixed(1)}k)`);
    }
  } else {
    lines.push("### No pure-strategy Nash equilibrium exists.");
  }

  lines.push("");

  // Mixed strategy
  if (e.mixedStrategy) {
    const m = e.mixedStrategy;
    lines.push(`### Mixed-Strategy Nash Equilibrium`);
    lines.push(`- **${params.nameYou}** plays Ad with probability **${(m.pYouAd * 100).toFixed(1)}%**`);
    lines.push(`- **${params.nameRival}** plays Ad with probability **${(m.qRivalAd * 100).toFixed(1)}%**`);
    lines.push(`- Expected payoff: **${params.nameYou}** $${m.yourExpectedPayoff.toFixed(1)}k, **${params.nameRival}** $${m.rivalExpectedPayoff.toFixed(1)}k`);
  }

  lines.push("");
  lines.push("### 💡 Interpretation");
  if (dom.you === "Ad") {
    lines.push(`> **You should advertise** — it's your dominant strategy regardless of what ${params.nameRival} does.`);
  } else if (dom.you === "NoAd") {
    lines.push(`> **You should NOT advertise** — skipping ads is your dominant strategy regardless of ${params.nameRival}.`);
  } else if (e.mixedStrategy) {
    const p = e.mixedStrategy.pYouAd;
    if (p > 0.6) lines.push(`> Advertising is likely the better play (${(p*100).toFixed(0)}% of equilibria mix), but it depends on what the rival does.`);
    else if (p < 0.4) lines.push(`> Not advertising is favored (${((1-p)*100).toFixed(0)}% of equilibria mix), but monitor the rival's moves.`);
    else lines.push(`> It's a close call — the mixed equilibrium suggests near-even odds. Consider other strategic factors.`);
  }

  return md(lines.join("\n"));
};

const _sensitivityChart = function sensitivityChart(gameMatrix, d3, html){
  // Sensitivity to adCost: how does your expected payoff change?
  const { raw } = gameMatrix;
  const costs = d3.range(0, 101, 5);
  const margin = {top: 30, right: 30, bottom: 40, left: 50};
  const width = 560, height = 300;
  const iw = width - margin.left - margin.right;
  const ih = height - margin.top - margin.bottom;

  const data = costs.map(cost => {
    const bm = raw.baseProfit;
    const mg = raw.marketGainFromAd;
    const ba = raw.bothAdGain;
    // If you Ad, rival Ad
    const pay_youAd_rivalAd = bm + ba - cost;
    // If you Ad, rival NoAd
    const pay_youAd_rivalNoAd = bm + mg - cost;
    // If you NoAd, rival Ad
    const pay_youNoAd_rivalAd = bm - mg * 0.3;
    // If you NoAd, rival NoAd
    const pay_youNoAd_rivalNoAd = bm;
    return { cost, pay_youAd_rivalAd, pay_youAd_rivalNoAd, pay_youNoAd_rivalAd, pay_youNoAd_rivalNoAd };
  });

  const x = d3.scaleLinear().domain([0, 100]).range([0, iw]);
  const y = d3.scaleLinear()
    .domain([d3.min(data, d => Math.min(d.pay_youAd_rivalAd, d.pay_youNoAd_rivalAd)) - 5,
             d3.max(data, d => Math.max(d.pay_youAd_rivalNoAd, d.pay_youNoAd_rivalNoAd)) + 5])
    .range([ih, 0]);

  const colors = { AdvsAd: "#1a73e8", AdvNoAd: "#34a853", NoAdvAd: "#e53935", NoAdvNoAd: "#fbbc04" };
  const line = d3.line().x(d => x(d.cost)).curve(d3.curveMonotoneX);

  const svg = d3.create("svg").attr("width", width).attr("height", height);
  const g = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);

  g.append("g").attr("transform", `translate(0,${ih})`).call(d3.axisBottom(x));
  g.append("g").call(d3.axisLeft(y));
  g.append("text").attr("x", iw/2).attr("y", ih + 35).attr("text-anchor", "middle").text("Ad Cost ($k)");
  g.append("text").attr("x", -ih/2).attr("y", -35).attr("transform", "rotate(-90)").attr("text-anchor", "middle").text("Your Payoff ($k)");

  // Current cost marker
  g.append("line")
    .attr("x1", x(raw.adCost)).attr("x2", x(raw.adCost))
    .attr("y1", 0).attr("y2", ih)
    .attr("stroke", "#999").attr("stroke-dasharray", "4,3");

  const paths = [
    { key: "pay_youAd_rivalAd", label: "You Ad, Rival Ad", color: colors.AdvsAd },
    { key: "pay_youAd_rivalNoAd", label: "You Ad, Rival NoAd", color: colors.AdvNoAd },
    { key: "pay_youNoAd_rivalAd", label: "You NoAd, Rival Ad", color: colors.NoAdvAd },
    { key: "pay_youNoAd_rivalNoAd", label: "You NoAd, Rival NoAd", color: colors.NoAdvNoAd },
  ];

  for (const p of paths) {
    g.append("path")
      .datum(data)
      .attr("fill", "none")
      .attr("stroke", p.color)
      .attr("stroke-width", 2)
      .attr("d", line.y(d => y(d[p.key])));
  }

  // Legend
  const legend = g.append("g").attr("transform", `translate(${iw - 180}, 5)`);
  paths.forEach((p, i) => {
    legend.append("line").attr("x1", 0).attr("x2", 15).attr("y1", i * 18).attr("y2", i * 18).attr("stroke", p.color).attr("stroke-width", 2);
    legend.append("text").attr("x", 20).attr("y", i * 18 + 4).attr("font-size", 11).text(p.label);
  });

  return html`<div>
    <h3>Sensitivity: Your Payoff vs Ad Cost</h3>
    <div style="font-size: 12px; color: #666; margin-bottom: 4px;">Dashed line = current ad cost setting</div>
    ${svg.node()}
  </div>`;
};

const _recommendation = function recommendation(equilibrium, params, gameMatrix, md){
  const e = equilibrium;
  const dom = e.dominantStrategies;
  const lines = ["## 🎯 Recommendation", ""];

  if (dom.you === "Ad") {
    lines.push("### **Advertise.** ✅");
    lines.push("");
    lines.push("Advertising is your **strictly dominant strategy** — you earn more by advertising");
    lines.push("no matter what the competitor does. This is the strongest possible signal.");
  } else if (dom.you === "NoAd") {
    lines.push("### **Do NOT advertise.** ❌");
    lines.push("");
    lines.push("Not advertising is your **strictly dominant strategy**. Save the budget.");
  } else if (e.pureEquilibria.length > 0) {
    const best = e.pureEquilibria.reduce((a, b) => a.yourPayoff > b.yourPayoff ? a : b);
    lines.push(`### **Best equilibrium: ${best.you === "Ad" ? "Advertise ✅" : "Don't Advertise ❌"}**`);
    lines.push("");
    if (best.you === "Ad") {
      lines.push("In the most favorable Nash equilibrium, you advertise. However, since there's");
      lines.push("no dominant strategy, the outcome depends on the competitor's behavior.");
      lines.push("Consider: first-mover advantage, signaling strength, or coordination mechanisms.");
    } else {
      lines.push("In the most favorable Nash equilibrium, you don't advertise. Both firms save costs.");
      lines.push("But be careful — if the competitor deviates, you may need to respond.");
    }
  } else {
    lines.push("### **Mixed strategy recommended.** 🎲");
    if (e.mixedStrategy) {
      const p = e.mixedStrategy.pYouAd;
      lines.push(`Advertise with ~${(p*100).toFixed(0)}% probability each quarter (or allocate ~${(p*100).toFixed(0)}% of budget).`);
    }
    lines.push("");
    lines.push("No pure equilibrium exists — the optimal play is randomized. In practice, this means");
    lines.push("you should be unpredictable: sometimes advertise, sometimes don't.");
  }

  lines.push("");
  lines.push("---");
  lines.push(`*Model assumes symmetric competitor. Adjust parameters above to reflect your market reality.*`);

  return md(lines.join("\n"));
};

export default function define(runtime, observer) {
  const main = runtime.module();
  const $def = (pid, name, deps, fn) => main.variable(observer(name)).define(name, deps, fn).pid = pid;
  $def("_intro", "intro", ["md"], _intro);
  $def("_params", "viewof params", ["htl", "Inputs"], _params);
  $def("_paramsVal", "params", ["Generators", "viewof params"], (G, v) => G.input(v));
  $def("_gameMatrix", "gameMatrix", ["params"], _gameMatrix);
  $def("_equilibrium", "equilibrium", ["gameMatrix", "params"], _equilibrium);
  $def("_payoffTable", "payoffTable", ["gameMatrix", "params", "html"], _payoffTable);
  $def("_equilibriumReport", "equilibriumReport", ["equilibrium", "params", "gameMatrix", "md"], _equilibriumReport);
  $def("_sensitivityChart", "sensitivityChart", ["gameMatrix", "d3", "html"], _sensitivityChart);
  $def("_recommendation", "recommendation", ["equilibrium", "params", "gameMatrix", "md"], _recommendation);
  return main;
}"}

